import sys
import os
import json

def load_records(packet_dir, document):
    """Load records from the file matching the given document name."""
    for fname in os.listdir(packet_dir):
        base, ext = os.path.splitext(fname)
        if base == document:
            file_path = os.path.join(packet_dir, fname)
            with open(file_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if isinstance(data, dict) and "results" in data:
                records = data["results"]
            elif isinstance(data, list):
                records = data
            else:
                records = []
            return records, base
    return [], document

def normalize_date(s):
    """Convert YYYYMMDD to YYYY-MM-DD. Leave already formatted dates unchanged."""
    if not s:
        return None
    s = s.strip()
    if len(s) == 8 and s.isdigit():
        return f"{s[:4]}-{s[4:6]}-{s[6:8]}"
    if len(s) == 10 and s[4] == '-' and s[7] == '-':
        return s
    return s

def get_field_value(records, field, doc_name):
    """Extract the value for a field from a list of records for one entity."""
    values = []
    for rec in records:
        val = rec.get(field, "")
        if val is None:
            val = ""
        if isinstance(val, str):
            val = val.strip()
        else:
            val = str(val).strip()
        if val == "":
            continue
        if field in ("recall_initiation_date", "center_classification_date", "termination_date"):
            norm = normalize_date(val)
            if norm:
                values.append(norm)
        else:
            values.append(val)
    distinct = list(set(values))
    if len(distinct) == 0:
        return "ABSENT"
    elif len(distinct) == 1:
        return [distinct[0], doc_name]
    else:
        return "CONFLICT"

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Mapping from rule_id and fact name to the establishing field, per decision rules.
    rule_fields = {
        "fda.classified_30d": {
            "initiation date": "recall_initiation_date",
            "classification date": "center_classification_date",
        },
        "fda.terminated_180d": {
            "initiation date": "recall_initiation_date",
            "termination date": "termination_date",
        },
    }

    document = "fda_enforcement_reports"
    records, doc_name = load_records(packet_dir, document)

    # Index records by recall_number (the entity identifier)
    index = {}
    for rec in records:
        rn = rec.get("recall_number", "")
        if rn:
            index.setdefault(rn, []).append(rec)

    output = {}
    for pair in manifest["pairs"]:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"].get(rule_id, [])
        result = {}
        for fact in facts:
            field = rule_fields.get(rule_id, {}).get(fact)
            if not field:
                result[fact] = "ABSENT"
                continue
            recs = index.get(entity, [])
            if not recs:
                result[fact] = "ABSENT"
            else:
                result[fact] = get_field_value(recs, field, doc_name)
        output[pair] = result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
