import json
import os
import sys
from datetime import datetime

# Decision rules: rule_id -> {fact_name: (document_name, field_name)}
RULES = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "classification date": ("fda_enforcement_reports", "center_classification_date"),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "termination date": ("fda_enforcement_reports", "termination_date"),
    },
}

# Fields that contain dates and need YYYY-MM-DD formatting
DATE_FIELDS = {"recall_initiation_date", "center_classification_date", "termination_date"}


def load_document(packet_dir, doc_name):
    """Load a JSON document from the packet directory. Returns None if not found or invalid."""
    file_path = os.path.join(packet_dir, doc_name + ".json")
    if not os.path.isfile(file_path):
        return None
    try:
        with open(file_path, "r", encoding="utf-8") as f:
            return json.load(f)
    except (json.JSONDecodeError, OSError):
        return None


def format_date(value):
    """Convert a date string to YYYY-MM-DD. Return None if not a valid date."""
    if not isinstance(value, str):
        return None
    value = value.strip()
    if not value:
        return None
    # Try YYYYMMDD format (e.g., "20200210")
    if len(value) == 8 and value.isdigit():
        try:
            dt = datetime.strptime(value, "%Y%m%d")
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            pass
    # Try YYYY-MM-DD format
    try:
        dt = datetime.strptime(value, "%Y-%m-%d")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass
    return None


def get_records_for_entity(doc_data, entity):
    """Return all records in the document that match the entity (recall_number)."""
    if not doc_data:
        return []
    results = doc_data.get("results", [])
    if not isinstance(results, list):
        return []
    return [
        rec
        for rec in results
        if isinstance(rec, dict) and str(rec.get("recall_number", "")).strip() == entity
    ]


def extract_fact(records, field_name, doc_name):
    """Extract the fact value from records. Return one of:
    - [value, doc_name]
    - "ABSENT"
    - "CONFLICT"
    """
    values = []
    is_date = field_name in DATE_FIELDS
    for rec in records:
        val = rec.get(field_name)
        if val is None:
            continue
        if isinstance(val, str):
            val = val.strip()
            if val == "":
                continue
        else:
            val = str(val)
        if is_date:
            formatted = format_date(val)
            if formatted is not None:
                values.append(formatted)
        else:
            values.append(val)
    if not values:
        return "ABSENT"
    unique = set(values)
    if len(unique) > 1:
        return "CONFLICT"
    return [values[0], doc_name]


def main():
    if len(sys.argv) != 3:
        sys.stderr.write("Usage: python3 program.py <packet_directory> <manifest.json>\n")
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_map = manifest.get("facts", {})

    doc_cache = {}
    output = {}

    for pair in pairs:
        pair = pair.strip()
        if "::" not in pair:
            output[pair] = {}
            continue
        rule_id, entity = pair.split("::", 1)
        rule_id = rule_id.strip()
        entity = entity.strip()
        fact_names = facts_map.get(rule_id, [])
        result_obj = {}
        for fact_name in fact_names:
            fact_name = fact_name.strip()
            if rule_id in RULES and fact_name in RULES[rule_id]:
                doc_name, field_name = RULES[rule_id][fact_name]
                if doc_name not in doc_cache:
                    doc_cache[doc_name] = load_document(packet_dir, doc_name)
                doc_data = doc_cache[doc_name]
                records = get_records_for_entity(doc_data, entity)
                result = extract_fact(records, field_name, doc_name)
                result_obj[fact_name] = result
            else:
                result_obj[fact_name] = "ABSENT"
        output[pair] = result_obj

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
