def parse_date(date_str):
    """Convert YYYYMMDD to YYYY-MM-DD"""
    if not date_str or len(date_str) != 8 or not date_str.isdigit():
        return None
    return f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"

